package dev.zomboid.gore;
public class Checks {static int n;static void check(boolean b){n++;if(!b)throw new AssertionError("rule "+n);}public static void main(String[]args){check(Rules.weapon("pistol")==Rules.Weapon.PISTOL);check(Rules.weapon("shotgun")==Rules.Weapon.SHOTGUN);check(Rules.weapon("sniper")==Rules.Weapon.SNIPER);check(Rules.zone(.95,0,true)==Rules.HEAD);check(Rules.zone(.83,0,true)==Rules.JAW);check(Rules.zone(.3,.3,false)==Rules.LEFT_LEG);check(Rules.zone(.3,-.3,false)==Rules.RIGHT_LEG);check(Rules.zone(.65,.35,false)==Rules.LEFT_ARM);check(Rules.zone(.65,-.35,false)==Rules.RIGHT_ARM);int pistol=Rules.update(0,Rules.LEFT_ARM,3,3,20,Rules.Weapon.PISTOL);check((pistol&255)==0);check((pistol&(1<<(8+Rules.LEFT_ARM)))!=0);int shot=Rules.update(0,Rules.LEFT_ARM,8,8,20,Rules.Weapon.SHOTGUN);check((shot&(1<<Rules.LEFT_ARM))!=0);check(Rules.attack(shot)<1);check(Rules.attack(12)<Rules.attack(4));int sniper=Rules.update(0,Rules.RIGHT_BODY,14,14,20,Rules.Weapon.SNIPER);check((sniper&(1<<(18+Rules.RIGHT_BODY)))!=0);check(Rules.speed(1)<1);check(Rules.crawling(16)&&Rules.speed(16)<=.25);check(Rules.speed(0)==1);check(Rules.charStage(19)==0);check(Rules.charStage(20)==1);check(Rules.charStage(60)==2);check(Rules.charStage(120)==3);check(Rules.update(shot,Rules.HEAD,2,2,20,Rules.Weapon.PISTOL)==(shot|(1<<8)));System.out.println("Gore rule checks: "+n);}}
